<script setup>
import { computed, ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../../Layouts/AppLayout.vue';
import RupiahInput from '../../../Components/Shared/RupiahInput.vue';
import { cartLine, choicesValid, money } from '../../../Support/cart.js';
defineOptions({ layout: AppLayout });
const props = defineProps({ storeName: String, items: Array, checkoutKey: String, cash: Boolean, qris: Boolean, submitUrl: String, backUrl: String });
const form = useForm({ idempotency_key: props.checkoutKey, customer_name: '', phone: '', method: 'pickup', payment_method: props.cash ? 'cash' : 'qris', cash_received: 0, keep_change: false, items: [] });
const selected = ref(''); const error = ref('');
const add = () => { const item = props.items.find(item => item.id === Number(selected.value)); if (item && form.items.length < 50) form.items.push({ id: item.id, quantity: 1, choices: [] }); };
const total = computed(() => form.items.reduce((sum, line) => sum + (cartLine(line, props.items)?.total || 0), 0));
const product = line => props.items.find(item => item.id === line.id);
const toggle = (line, group, id) => { if(group.selection === 'single') line.choices = [...line.choices.filter(value => !group.choices.some(choice => choice.id === value)), id]; else line.choices = line.choices.includes(id) ? line.choices.filter(value => value !== id) : [...line.choices,id]; };
const submit = () => { error.value = ''; if(form.items.some(line => !choicesValid(product(line), line.choices))) { error.value = 'Complete the required product choices.'; return; } form.post(props.submitUrl); };
</script>
<template>
<Head title="Create order"/><Link :href="backUrl" class="text-sm text-stone-500">← Orders</Link>
<form @submit.prevent="submit" class="mx-auto mt-6 max-w-3xl space-y-6"><div><p class="text-sm text-stone-500">{{ storeName }}</p><h1 class="mt-2 text-3xl font-semibold">Create order</h1><p class="mt-3 text-sm text-stone-500">For customers ordering at your store.</p></div>
<section class="space-y-4 rounded-2xl border border-stone-200 bg-white p-5"><div class="flex flex-wrap gap-3"><select v-model="selected" class="min-w-0 flex-1 rounded-xl border border-stone-300 p-3" aria-label="Product"><option value="">Choose a product</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.name }} · {{ money(item.price) }}</option></select><button type="button" class="rounded-xl bg-[#504941] px-5 py-3 text-white" @click="add">Add</button></div>
<article v-for="(line,index) in form.items" :key="index" class="space-y-4 border-t border-stone-200 py-4"><div class="flex items-center justify-between gap-3"><strong>{{ product(line).name }}</strong><button type="button" class="rounded-lg px-3 py-2 text-red-700" @click="form.items.splice(index,1)">Remove</button></div><fieldset v-for="group in product(line).options" :key="group.id"><legend class="mb-2 text-sm">{{ group.name }} {{ group.required ? '· Required' : '· Optional' }}</legend><div class="flex flex-wrap gap-2"><label v-for="choice in group.choices" :key="choice.id" class="flex items-center gap-2 rounded-xl border border-stone-200 px-3 py-2 text-sm"><input :type="group.selection === 'single' ? 'radio' : 'checkbox'" :name="`${index}-${group.id}`" :checked="line.choices.includes(choice.id)" @change="toggle(line,group,choice.id)">{{ choice.name }} {{ choice.price_adjustment ? '+' + money(choice.price_adjustment) : '' }}</label></div></fieldset><div class="flex items-center justify-between"><label class="text-sm">Quantity <input v-model.number="line.quantity" type="number" min="1" max="99" required class="ml-3 w-20 rounded-lg border border-stone-300 p-2"></label><span>{{ money(cartLine(line,items)?.total || 0) }}</span></div></article></section>
<section class="grid gap-4 rounded-2xl border border-stone-200 bg-white p-5 sm:grid-cols-2"><label class="text-sm">Customer name · Optional<input v-model="form.customer_name" maxlength="100" class="mt-2 w-full rounded-xl border border-stone-300 p-3"></label><label class="text-sm">WhatsApp number · Optional<input v-model="form.phone" type="tel" maxlength="30" class="mt-2 w-full rounded-xl border border-stone-300 p-3"></label></section>
<section class="space-y-4 rounded-2xl border border-stone-200 bg-white p-5"><p class="flex justify-between text-xl font-semibold"><span>Total</span>{{ money(total) }}</p><div class="flex gap-5"><label v-if="cash" class="flex gap-2"><input v-model="form.payment_method" type="radio" value="cash">Cash</label><label v-if="qris" class="flex gap-2"><input v-model="form.payment_method" type="radio" value="qris">QRIS</label></div><template v-if="form.payment_method === 'cash'"><RupiahInput v-model="form.cash_received" name="walk-in-cash" label="Cash received" required/><label class="flex items-center gap-2 text-sm"><input v-model="form.keep_change" type="checkbox">Customer leaves the change</label><p class="text-sm">Change: {{ money(form.keep_change ? 0 : Math.max(0,Number(form.cash_received)-total)) }}</p></template><p v-else class="text-sm text-stone-500">Show the payment QR to the customer after creating this order.</p><p v-if="error" role="alert" class="text-sm text-red-700">{{ error }}</p><p v-for="(message,key) in form.errors" :key="key" role="alert" class="text-sm text-red-700">{{ message }}</p><button :disabled="form.processing || !form.items.length || (!cash && !qris)" class="w-full rounded-full bg-[#504941] px-5 py-3 text-white disabled:opacity-40">{{ form.processing ? 'Saving…' : 'Create order' }}</button></section></form>
</template>
